157→// RefreshFromInsightsDB checks if the cache is stale and repopulates if needed.
158→// Returns true if the cache was refreshed.
159→func (sdb *SkillDB) RefreshFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow) (bool, error) {
160→	// Check insightsdb branch tip.
161→	currentTip, err := idb.GetBranchTip(ctx)
162→	if err != nil {
163→		return false, fmt.Errorf("get insightsdb branch tip: %w", err)
164→	}
165→
166→	cachedTip, err := sdb.GetCacheTip(ctx)
167→	if err != nil {
168→		return false, fmt.Errorf("get skilldb cache tip: %w", err)
169→	}
170→
171→	if currentTip != "" && currentTip == cachedTip {
172→		return false, nil
173→	}
174→
175→	// Upsert discovered skills.
176→	now := time.Now().UTC()
177→	for _, skill := range discoveredSkills {
178→		if err = sdb.UpsertSkill(ctx, SkillRow{
179→			Name:         skill.Name,
180→			SourceAgent:  skill.SourceAgent,
181→			Path:         skill.Path,
182→			Kind:         skill.Kind,
183→			DiscoveredAt: now,
184→			LastSeenAt:   now,
185→		}); err != nil {
186→			return false, fmt.Errorf("upsert skill %q: %w", skill.Name, err)
187→		}
188→	}
189→
190→	// Clear existing session data before repopulating.
191→	if err = sdb.clearSessionData(ctx); err != nil {
192→		return false, fmt.Errorf("clear session data: %w", err)
193→	}
194→
195→	// Populate from insightsdb.
196→	if err = sdb.PopulateFromInsightsDB(ctx, idb, discoveredSkills); err != nil {
197→		return false, fmt.Errorf("populate from insightsdb: %w", err)
198→	}
199→
200→	// Update cache tip.
201→	if currentTip != "" {
202→		if err = sdb.SetCacheTip(ctx, currentTip); err != nil {
203→			return false, fmt.Errorf("set cache tip: %w", err)
204→		}
205→	}
206→
207→	return true, nil
208→}
