 11→// DiscoveredSkill represents a skill file found in an agent's config directory.
 12→type DiscoveredSkill struct {
 13→	Name        string // skill name (e.g., "e2e", "dev")
 14→	SourceAgent string // "claude-code" or "gemini-cli"
 15→	Path        string // relative path from repo root (e.g., ".claude/skills/e2e/SKILL.md")
 16→	Kind        string // "skill", "command", or "agent-def"
 17→}
 18→
 19→// DiscoverSkills scans repoRoot for skill files across agent config directories.
 20→// Missing directories are silently skipped.
 21→func DiscoverSkills(repoRoot string) ([]DiscoveredSkill, error) {
 22→	var skills []DiscoveredSkill
 23→
 24→	collectors := []struct {
 25→		pattern     string
 26→		sourceAgent string
 27→		kind        string
 28→		nameFunc    func(match string) string
 29→		readContent bool
 30→	}{
 31→		{
 32→			pattern:     filepath.Join(repoRoot, ".claude", "skills", "*", "SKILL.md"),
 33→			sourceAgent: "claude-code",
 34→			kind:        "skill",
 35→			nameFunc:    func(match string) string { return filepath.Base(filepath.Dir(match)) },
 36→		},
 37→		{
 38→			pattern:     filepath.Join(repoRoot, ".claude", "commands", "*.md"),
 39→			sourceAgent: "claude-code",
 40→			kind:        "command",
 41→			nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
 42→		},
 43→		{
 44→			pattern:     filepath.Join(repoRoot, ".gemini", "agents", "*.md"),
 45→			sourceAgent: "gemini-cli",
 46→			kind:        "agent-def",
 47→			readContent: true,
 48→			nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
 49→		},
 50→		{
 51→			pattern:     filepath.Join(repoRoot, ".gemini", "commands", "*.md"),
 52→			sourceAgent: "gemini-cli",
 53→			kind:        "command",
 54→			readContent: true,
 55→			nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
 56→		},
 57→	}
 58→
 59→	for _, c := range collectors {
 60→		matches, err := filepath.Glob(c.pattern)
 61→		if err != nil {
 62→			return nil, fmt.Errorf("globbing %s: %w", c.pattern, err)
 63→		}
 64→
 65→		for _, match := range matches {
 66→			name := c.nameFunc(match)
 67→
 68→			if c.readContent {
 69→				content, err := os.ReadFile(match) //nolint:gosec // match comes from filepath.Glob, not user input
 70→				if err != nil {
 71→					return nil, fmt.Errorf("reading %s: %w", match, err)
 72→				}
 73→				if yamlName := extractYAMLName(string(content)); yamlName != "" {
 74→					name = yamlName
 75→				}
 76→			}
 77→
 78→			relPath, err := filepath.Rel(repoRoot, match)
 79→			if err != nil {
 80→				return nil, fmt.Errorf("computing relative path for %s: %w", match, err)
 81→			}
 82→
 83→			skills = append(skills, DiscoveredSkill{
 84→				Name:        name,
 85→				SourceAgent: c.sourceAgent,
 86→				Path:        relPath,
 87→				Kind:        c.kind,
 88→			})
 89→		}
 90→	}
 91→
 92→	sort.Slice(skills, func(i, j int) bool {
 93→		if skills[i].SourceAgent != skills[j].SourceAgent {
 94→			return skills[i].SourceAgent < skills[j].SourceAgent
 95→		}
 96→		return skills[i].Name < skills[j].Name
 97→	})
 98→
 99→	return skills, nil
100→}
101→
102→// extractYAMLName looks for a name field in YAML frontmatter delimited by "---".
103→func extractYAMLName(content string) string {
104→	lines := strings.Split(content, "\n")
105→	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
106→		return ""
107→	}
108→
109→	for _, line := range lines[1:] {
110→		trimmed := strings.TrimSpace(line)
111→		if trimmed == "---" {
112→			break
113→		}
114→		if strings.HasPrefix(trimmed, "name:") {
115→			value := strings.TrimPrefix(trimmed, "name:")
116→			return strings.TrimSpace(value)
117→		}
118→	}
119→
120→	return ""
121→}
