package main

import (
	"fmt"
	"strings"
)

type SkillRow struct {
	Name        string
	SourceAgent string
}

func resolveSkillName(signalName string, skillMap map[string]SkillRow) (SkillRow, bool) {
	if skill, ok := skillMap[signalName]; ok {
		return skill, true
	}
	if idx := strings.IndexByte(signalName, ':'); idx > 0 {
		parent := signalName[:idx]
		if skill, ok := skillMap[parent]; ok {
			return skill, true
		}
	}
	if idx := strings.LastIndexByte(signalName, ':'); idx >= 0 && idx < len(signalName)-1 {
		lastSeg := signalName[idx+1:]
		if skill, ok := skillMap[lastSeg]; ok {
			return skill, true
		}
	}
	for name, skill := range skillMap {
		if len(name) < 2 { continue }
		searchIn := signalName
		for {
			idx := strings.Index(searchIn, name)
			if idx < 0 { break }
			leftOK := idx == 0 || searchIn[idx-1] == '-' || searchIn[idx-1] == ':'
			rightEnd := idx + len(name)
			rightOK := rightEnd == len(searchIn) || searchIn[rightEnd] == '-' || searchIn[rightEnd] == ':'
			if leftOK && rightOK { return skill, true }
			searchIn = searchIn[idx+1:]
		}
	}
	return SkillRow{}, false
}

func main() {
	skills := map[string]SkillRow{
		"agent-integration": {Name: "agent-integration", SourceAgent: "claude-code"},
		"analyst":           {Name: "analyst", SourceAgent: "claude-code"},
		"dev":               {Name: "dev", SourceAgent: "claude-code"},
		"dev-cycle":         {Name: "dev-cycle", SourceAgent: "claude-code"},
		"e2e":               {Name: "e2e", SourceAgent: "claude-code"},
		"reviewer":          {Name: "reviewer", SourceAgent: "claude-code"},
		"test-doc":          {Name: "test-doc", SourceAgent: "gemini-cli"},
		"test-repo":         {Name: "test-repo", SourceAgent: "claude-code"},
	}

	signals := []string{"cli-e2e-failure-fix", "e2e:triage", "e2e:implement", "simplify", "superpowers:writing-plans"}
	for _, sig := range signals {
		skill, ok := resolveSkillName(sig, skills)
		if ok {
			fmt.Printf("  %s -> %s (%s)\n", sig, skill.Name, skill.SourceAgent)
		} else {
			fmt.Printf("  %s -> NO MATCH\n", sig)
		}
	}
}
