454→func (m rootModel) generateSuggestions() tea.Cmd {
455→	return func() tea.Msg {
456→		if m.selectedSkill == nil {
457→			return generateDoneMsg{err: errors.New("no skill selected")}
458→		}
459→
460→		skill := *m.selectedSkill
461→
462→		// Read skill file content.
463→		skillPath := filepath.Join(m.repoRoot, skill.Path)
464→		content, err := os.ReadFile(skillPath) //nolint:gosec // path is constructed from repo root + db path
465→		if err != nil {
466→			return generateDoneMsg{err: fmt.Errorf("read skill file: %w", err)}
467→		}
468→
469→		// Load data needed for the request.
470→		stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
471→		if err != nil {
472→			return generateDoneMsg{err: fmt.Errorf("load stats: %w", err)}
473→		}
474→
475→		friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
476→		if err != nil {
477→			return generateDoneMsg{err: fmt.Errorf("load friction: %w", err)}
478→		}
479→
480→		missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
481→		if err != nil {
482→			return generateDoneMsg{err: fmt.Errorf("load missing: %w", err)}
483→		}
484→
485→		agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
486→		if err != nil {
487→			return generateDoneMsg{err: fmt.Errorf("load agents: %w", err)}
488→		}
489→
490→		// Build the request.
491→		frictionRate := 0.0
492→		if stats.TotalSessions > 0 {
493→			frictionRate = float64(stats.TotalFriction) / float64(stats.TotalSessions) * 100
494→		}
495→
496→		var frictionThemes []skillimprove.FrictionTheme
497→		for _, f := range friction {
498→			frictionThemes = append(frictionThemes, skillimprove.FrictionTheme{
499→				Text:     f.Text,
500→				Category: f.Category,
501→				Count:    f.Count,
502→			})
503→		}
504→
505→		var missingInstructions []skillimprove.MissingInstruction
506→		for _, mi := range missing {
507→			missingInstructions = append(missingInstructions, skillimprove.MissingInstruction{
508→				Instruction: mi.Instruction,
509→				Count:       mi.Count,
510→				Evidence:    mi.Evidence,
511→			})
512→		}
513→
514→		var agentBreakdown []skillimprove.AgentStats
515→		for _, a := range agents {
516→			agentBreakdown = append(agentBreakdown, skillimprove.AgentStats{
517→				Agent:        a.Agent,
518→				SessionCount: a.SessionCount,
519→				AvgScore:     a.AvgScore,
520→			})
521→		}
522→
523→		req := skillimprove.SkillImprovementRequest{
524→			SkillName:           skill.Name,
525→			SkillPath:           skill.Path,
526→			SkillContent:        string(content),
527→			FrictionThemes:      frictionThemes,
528→			MissingInstructions: missingInstructions,
529→			TotalSessions:       stats.TotalSessions,
530→			FrictionRate:        frictionRate,
531→			AgentBreakdown:      agentBreakdown,
532→		}
533→
534→		result, err := m.generator.Generate(m.ctx, req)
535→		if err != nil {
536→			return generateDoneMsg{err: err}
537→		}
538→
539→		return generateDoneMsg{suggestions: result.Suggestions}
540→	}
