543→func (m rootModel) applyDiff(index int) tea.Cmd {
544→	return func() tea.Msg {
545→		if index >= len(m.improveTab.suggestions) || m.selectedSkill == nil {
546→			return applyDiffResultMsg{index: index, err: errors.New("invalid suggestion index")}
547→		}
548→
549→		sug := m.improveTab.suggestions[index]
550→		skillPath := filepath.Join(m.repoRoot, m.selectedSkill.Path)
551→
552→		if err := skillimprove.ApplyDiff(skillPath, sug.Diff); err != nil {
553→			return applyDiffResultMsg{index: index, err: fmt.Errorf("apply diff: %w", err)}
554→		}
555→
556→		// Record the applied improvement in the database.
557→		imp := skilldb.SkillImprovement{
558→			ID:          fmt.Sprintf("%d-%s", time.Now().UnixNano(), m.selectedSkill.Name),
559→			SkillName:   m.selectedSkill.Name,
560→			SourceAgent: m.selectedSkill.SourceAgent,
561→			Title:       sug.Title,
562→			Description: sug.Description,
563→			Diff:        sug.Diff,
564→			Priority:    sug.Priority,
565→			Status:      "applied",
566→			CreatedAt:   time.Now().UTC(),
567→		}
568→		appliedAt := time.Now().UTC()
569→		imp.AppliedAt = &appliedAt
570→
571→		if err := m.skillDB.InsertImprovement(m.ctx, imp); err != nil {
572→			// Non-fatal: diff was applied but recording failed.
573→			return applyDiffResultMsg{index: index, err: nil}
574→		}
575→
576→		return applyDiffResultMsg{index: index, err: nil}
577→	}
578→}
